    if(!t)ss.forEach(function(s){if(!t&&/اليوم/.test(s)&&s.length>=22&&s.length<=170)t=s});
    if(!t){var rs=sentences(m.r||"");var l=rs[rs.length-1];if(l&&/اليوم/.test(l)&&l.length>=22&&l.length<=170&&!/؟$/.test(l))t=l}
